#include "../src/learning/memory_system.h"
#include "../src/learning/learning_controller.h"
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <random>
namespace {
struct R{double accuracy=0,restart_accuracy=0,control_accuracy=0;uint32_t replay=0;bool restart=false;uint64_t violations=0;};
void setup(genesis::NeuronBlock&n,genesis::SynapseBlock&s,size_t slots){n.resize(slots*2+1);for(float&x:n.plasticity_scale)x=1;s.resize(slots*2);s.weights.assign(slots*2,.5f);s.precision_scale.assign(slots*2,1);s.pre_indices.assign(slots*2,0);s.post_indices.resize(slots*2);for(size_t i=0;i<slots*2;++i)s.post_indices[i]=(uint32_t)(i+1);}
int pick(const genesis::SynapseBlock&s,size_t base){return s.weights[base]>=s.weights[base+1]?0:1;}
void learn(genesis::LearningController&l,genesis::SynapseBlock&s,genesis::NeuronBlock&n,size_t base,int a,float reward,uint64_t t){size_t id=base+(size_t)a;l.on_pre_spike((uint32_t)id,s,t);l.on_post_spike((uint32_t)(id+1),s,t+1);genesis::LearningSignal q;q.reward=reward;q.tick=t+1;l.apply_modulation(q);l.update(s,n,t+1);l.reset_traces(s);}
int target(int task,int context){return task==0?context:1-context;}
R run(uint64_t seed,bool contextual,const std::filesystem::path&dir){std::filesystem::create_directories(dir);size_t slots=contextual?4:2;genesis::LearningConfig c;c.eta=.05f;c.trace_decay=.95f;c.a_plus=.5f;c.a_minus=.1f;c.reward_coefficient=1;c.prediction_error_coefficient=0;c.novelty_coefficient=0;c.task_relevance_coefficient=0;c.executive_permission_coefficient=0;c.homeostasis_enabled=false;c.structural_enabled=false;c.weight_min=.01f;c.weight_max=1;genesis::NeuronBlock n;genesis::SynapseBlock s;setup(n,s,slots);genesis::LearningController l(c);l.initialize(n.plasticity_scale.size(),s.weights.size());genesis::MemoryConfig mc;mc.replay_quota_per_context=100;genesis::MemorySystem mem(seed,mc);mem.initialize_arena(n.plasticity_scale.size(),s.weights.size());uint64_t tick=1;uint32_t replay=0;
 for(size_t ep=0;ep<4000;++ep){int task=(int)(ep%2),ctx=(int)((ep/2)%2),a=(int)(ep%2);size_t slot=contextual?(size_t)(task*2+ctx):(size_t)ctx;learn(l,s,n,slot*2,a,a==target(task,ctx)?1:-1,tick);genesis::EventHeader h{ep+1,tick,1,100,(uint64_t)(task*2+ctx),seed};auto id=mem.begin_episode(h);mem.set_active_metrics(.3f,0,0,a==target(task,ctx)?1:-1);mem.close_episode(id,a==target(task,ctx)?1:-1);tick+=4;}
 if(contextual){mem.set_replay_callback([&](const genesis::MemoryEvent&e,genesis::ReplayMode){size_t slot=(size_t)(e.header.payload_id%4);int a=pick(s,slot*2);learn(l,s,n,slot*2,a,a==target((int)(slot/2),(int)(slot%2))?1:-1,tick++);++replay;});auto selected=mem.select_replay({0,0,tick},200);mem.replay(selected,genesis::ReplayMode::ExactEvent,10000);}
 size_t good=0;for(int task=0;task<2;++task)for(int ctx=0;ctx<2;++ctx)for(size_t i=0;i<250;++i){size_t slot=contextual?(size_t)(task*2+ctx):(size_t)ctx;good+=pick(s,slot*2)==target(task,ctx)?1:0;}R r;r.accuracy=(double)good/1000;r.control_accuracy=0;r.replay=replay;
 std::ofstream weights(dir/"weights.state");for(float w:s.weights)weights<<std::setprecision(10)<<w<<'\n';weights.close();genesis::SynapseBlock restored; restored.resize(s.weights.size()); restored.weights.assign(s.weights.size(),0.0f); std::ifstream in(dir/"weights.state"); for(float&w:restored.weights) in>>w;size_t rg=0;for(int task=0;task<2;++task)for(int ctx=0;ctx<2;++ctx)for(size_t i=0;i<250;++i){size_t slot=contextual?(size_t)(task*2+ctx):(size_t)ctx;rg+=pick(restored,slot*2)==target(task,ctx)?1:0;}r.restart_accuracy=(double)rg/1000;r.restart=restored.weights==s.weights;r.violations=l.metrics().bound_violations;mem.save(dir/"memory.bin");return r;}
}
int main(int ac,char**av){uint64_t seed=ac>1?std::stoull(av[1]):424242;std::filesystem::path d=ac>2?av[2]:"artifacts/contextual-decision";std::filesystem::create_directories(d);R control=run(seed,false,d/"control"),yes=run(seed,true,d/"contextual");bool pass=yes.accuracy>=.8&&yes.restart_accuracy>=.8&&yes.replay>0&&yes.restart&&yes.violations==0&&yes.accuracy-control.accuracy>=.2;std::ofstream o(d/"summary.txt");o<<"B3_CONTEXTUAL_DECISION="<<(pass?"PASS":"FAIL")<<'\n'<<"no_context_accuracy="<<control.accuracy<<'\n'<<"contextual_accuracy="<<yes.accuracy<<'\n'<<"restart_accuracy="<<yes.restart_accuracy<<'\n'<<"replay_events="<<yes.replay<<'\n'<<"restart_match="<<(yes.restart?1:0)<<'\n'<<"bound_violations="<<yes.violations<<'\n';std::cout<<"B3_CONTEXTUAL_DECISION="<<(pass?"PASS":"FAIL")<<'\n'<<std::fixed<<std::setprecision(4)<<"no_context="<<control.accuracy<<" contextual="<<yes.accuracy<<" restart="<<yes.restart_accuracy<<" replay="<<yes.replay<<'\n';return pass?0:1;}
